#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum PreMajorInferencePolicy {
    #[default]
    Off,
    /// Downgrades an inferred Major bump to Minor.
    Conservative,
    /// Downgrades an inferred Major bump to Minor, and Minor to Patch.
    ConservativeFeat,
}

pub fn parse_publish_target(s: &str) -> Result<PublishTarget, ConfigError> {
    match s {
        "crates-io" => Ok(PublishTarget::CratesIo),
        "npm" => Ok(PublishTarget::Npm {
            registry: None,
            access: None,
        }),
        "pypi" => Ok(PublishTarget::Pypi { index: None }),
        "nuget" => Ok(PublishTarget::NuGet { source: None }),
        "github-release" => Ok(PublishTarget::GitHubRelease),
        "none" => Ok(PublishTarget::None),
        other => Err(ConfigError::UnknownKey {
            path: PathBuf::new(),
            key: format!("publish-to = {other:?}"),
        }),
    }
}

pub fn parse_release_trigger(s: &str) -> Result<ReleaseTrigger, ConfigError> {
    match s {
        "changeset" => Ok(ReleaseTrigger::Changeset),
        "auto" => Ok(ReleaseTrigger::Auto),
        other => Err(ConfigError::UnknownKey {
            path: PathBuf::new(),
            key: format!("release-trigger = {other}"),
        }),
    }
}

/// A `[[package]]` rule applies to a package when it has a manifest in the rule's ecosystem whose own name is the
/// rule's name.
///
/// `native_names` is the package's name in each ecosystem it has a manifest in. A dual package's names can differ per
/// ecosystem, so `npm/michi-node` does not apply to the package whose npm name is `@orin-dx/michi`, whatever its
/// directory or Cargo name is, which is the same identity a `[[fixed-group]]` member must give.
pub(crate) fn rule_applies(rule_id: &PackageId, native_names: &[(Ecosystem, &str)]) -> bool {
    rule_id.ecosystem().is_some_and(|eco| {
        native_names
            .iter()
            .any(|(ecosystem, name)| *ecosystem == eco && *name == rule_id.name())
    })
}

/// The first `[[package]]` rule, in TOML declaration order, that applies to `id`; `None` if none does.
///
/// MUST NOT sort or partition `cfg.packages`: declaration order is the specificity.
pub(crate) fn resolve_package_config<'a>(
    native_names: &[(Ecosystem, &str)],
    cfg: &'a ResolvedConfig,
) -> Option<&'a PackageConfig> {
    cfg.packages
        .iter()
        .find(|(rule_id, _)| rule_applies(rule_id, native_names))
        .map(|(_, pcfg)| pcfg)
}

pub fn parse_pre_major_policy(s: &str) -> Result<PreMajorInferencePolicy, ConfigError> {
    match s {
        "off" | "false" => Ok(PreMajorInferencePolicy::Off),
        "conservative" => Ok(PreMajorInferencePolicy::Conservative),
        "conservative-feat" => Ok(PreMajorInferencePolicy::ConservativeFeat),
        _ => Err(ConfigError::InvalidPreMajorInference { found: s.to_string() }),
    }
}

/// Parses the five override fields shared by `[[package]]` and
/// `[[package-set]]` blocks (release-trigger, tag-template, changelog,
/// pre-major-inference, publish-to) into a `PackageConfig`.
///
/// `previous_tag_templates` is `[[package]]`-only; `[[package-set]]` callers pass `None`.
#[allow(clippy::too_many_arguments)]
fn parse_package_config_fields(
    callisto_toml: &Path,
    error_prefix: &str,
    pattern_display: &str,
    release_trigger: Option<&str>,
    tag_template: Option<&str>,
    previous_tag_templates: Option<&[String]>,
    changelog: Option<&str>,
    pre_major_inference: Option<&str>,
    publish_to: Option<&[String]>,
) -> Result<PackageConfig, ConfigError> {
    let release_trigger = release_trigger.map(parse_release_trigger).transpose()?;

    let tag_template = tag_template
        .map(TagTemplate::parse)
        .transpose()
        .map_err(ConfigError::Tag)?;

    let previous_tag_templates = previous_tag_templates
        .unwrap_or_default()
        .iter()
        .map(|template| TagTemplate::parse(template))
        .collect::<Result<Vec<_>, _>>()
        .map_err(ConfigError::Tag)?;

    let changelog = changelog
        .map(|s| {
            callisto_model::workspace_relative(s).map_err(|_err| ConfigError::InvalidChangelogPath {
                pattern: pattern_display.to_string(),
                value: s.to_string(),
            })
        })
        .transpose()?;

    let pre_major_inference = pre_major_inference.map(parse_pre_major_policy).transpose()?;

    let publish_to = publish_to
        .map(|targets| {
            targets
                .iter()
                .map(|s| parse_publish_target(s))
                .collect::<Result<Vec<_>, _>>()
        })
        .transpose()
        .map_err(|e| match e {
            ConfigError::UnknownKey { key, .. } => ConfigError::UnknownKey {
                path: callisto_toml.to_path_buf(),
                key: format!("{error_prefix} publish-to: {key}"),
            },
            other => other,
        })?;

    Ok(PackageConfig {
        release_trigger,
        publish_to,
        tag_template,
        previous_tag_templates,
        changelog,
        pre_major_inference,
    })
}

/// Reads and parses `root/callisto.toml` (absent means empty), then [`resolve`]s it.
pub fn load(root: &Path) -> Result<ResolvedConfig, ConfigError> {
    let callisto_toml = root.join("callisto.toml");
    let content = callisto_model::strict_fs::read_optional(&callisto_toml).map_err(|e| ConfigError::Read {
        path: callisto_toml.clone(),
        message: e.to_string(),
    })?;
    let raw = if let Some(content) = content {
    #[error("{context}: `{given}` does not name its ecosystem")]
    #[diagnostic(
        code(E317),
        help("Write the ecosystem and name with a slash, such as `cargo/{given}`, `npm/{given}` or `pypi/{given}`.")
    )]
    BareReference { context: String, given: String },

    #[error("`[registries.{registry}]` does not say what kind of registry it is")]
    #[diagnostic(
        code(E321),
        help("Add `kind = \"cargo\"`, `kind = \"npm\"` or `kind = \"pypi\"` to `[registries.{registry}]`. Only the built-in `cratesIo`, `npm` and `pypi` registries may leave it out.")
    )]
    RegistryKindMissing { registry: String },

    #[error("group `{group}` has no members")]
    #[diagnostic(code(E251), help("Add at least one member to the group, or remove the group."))]
    EmptyGroup { group: GroupName },

    #[error("duplicate group name `{group}`")]
    #[diagnostic(code(E252), help("Rename one of the two groups sharing this name."))]
    DuplicateGroupName { group: GroupName },
    #[error("`{path}` sets unknown callisto key `{key}`")]
    #[diagnostic(code(E254), help("Remove or fix the unrecognized key `{}` in `{}`.", key, path.display()))]
    UnknownKey { path: PathBuf, key: String },

    #[error("`cascade.bump-severity` is `{found}`; expected `patch` or `minor`")]
    #[diagnostic(
        code(E255),
        help("Set `cascade.bump-severity` to `patch` or `minor` in callisto.toml.")
    )]
    InvalidBumpSeverity { found: String },

    #[error("`pre-major-inference` is `{found}`; expected `off`, `conservative`, or `conservative-feat`")]
    #[diagnostic(
        code(E256),
        help("Set `pre-major-inference` to `off`, `conservative`, or `conservative-feat` in callisto.toml.")
    )]
    InvalidPreMajorInference { found: String },

    #[error(
        "changesets.dir `{dir}` is an absolute path or contains `..` path components and would escape the workspace root"
    )]
    #[diagnostic(
        code(E116),
        help("Use a forward-slash-separated path relative to the workspace root that is not absolute and does not contain '..' components.")
    )]
    InvalidChangesetsDir { dir: String },

    #[error("`changelog = \"{value}\"` on `{pattern}` is an absolute path or contains `..` path components and would escape the workspace root")]
    #[diagnostic(
        code(E113),
        help("Use a forward-slash-separated path relative to the package root that does not contain '..' components.")
    )]
    InvalidChangelogPath { pattern: String, value: String },

    #[error("invalid product release configuration: {detail}")]
    #[diagnostic(
        code(E197),
        help("Configure one supported product package and its artifact targets.")
    )]
    InvalidProductRelease { detail: String },

    #[error(transparent)]
    #[diagnostic(transparent)]
    Tag(#[from] TagTemplateError),

    #[error(transparent)]
    #[diagnostic(transparent)]
    VersionParse(#[from] VersionParseError),
}

impl GraphError {
    /// E102 for `id`, suggesting up to three of `known` whose names are a small edit away.
    pub fn unknown_package(id: PackageId, known: impl IntoIterator<Item = PackageId>) -> Self {
        let hint = did_you_mean(&id, known);
        Self::UnknownPackage { id, hint }
    }

    /// The one filesystem path this error is about, when it carries it as a structured field.
    pub fn path(&self) -> Option<&std::path::Path> {
        match self {
            Self::Config(error) => error.path(),
            Self::ParseChangeset { path, .. }
            | Self::UnexpectedManifestVersion { path, .. }
            | Self::PartialVersionRun { path, .. }
            | Self::ApplyIo { path, .. }
            | Self::UnsafeArtifactPath { path, .. }
            | Self::ArtifactRead { path, .. }
            | Self::ArtifactBytesMismatch { path }
            | Self::ArtifactAttestation { path, .. }
            | Self::ReleaseInputRead { path, .. }
            | Self::ReleaseDecisionDecode { path, .. }
            | Self::InitAlreadyInitialized { path }
            | Self::InitIo { path, .. }
            | Self::InitWorkflowExists { path } => Some(path),
            _ => None,
        }
    }
}

impl ConfigError {
    /// The one filesystem path this error is about, when it carries it as a structured field.
    pub fn path(&self) -> Option<&std::path::Path> {
        match self {
            Self::Read { path, .. }
            | Self::ParseToml { path, .. }
            | Self::UnknownField { path, .. }
            | Self::InvalidValue { path, .. }
            | Self::UnknownKey { path, .. } => Some(path),
            _ => None,
        }
    }

    /// Rejects a colon-qualified package reference (`cargo:foo`); the slash form (`cargo/foo`) is the only qualified spelling.
    pub fn reject_colon_form(raw: &str, context: &str) -> Result<(), Self> {
        match PackageId::colon_form_canonical(raw) {
            Some(canonical) => Err(Self::ColonReference {
                context: context.to_owned(),
                given: raw.to_owned(),
                canonical,
            }),

