#![cfg(unix)]

//! Black-box tests that `release artifact-manifest` only digests the exact regular files an
//! intent declares: anything else in the artifact directory is refused or ignored, never
//! followed, and a failed run leaves no manifest behind.

#[path = "common/release_harness.rs"]
mod release_harness;

use std::{fs, os::unix::fs::symlink, path::Path, process::Output};

use release_harness::*;

const ASSET: &str = "callisto-moon.wasm";

struct Product {
    _repo: tempfile::TempDir,
    external: tempfile::TempDir,
    root: std::path::PathBuf,
    intent: std::path::PathBuf,
    artifacts: std::path::PathBuf,
}

fn product() -> Product {
    let (repo, release_commit) = product_release_commit_fixture();
    let external = tempfile::tempdir().unwrap();
    let root = repo.path().to_path_buf();
    let intent = plan_product_intent(&root, external.path(), &release_commit);
    let artifacts = create_product_artifacts(external.path());
    Product {
        _repo: repo,
        external,
        root,
        intent,
        artifacts,
    }
}

fn manifest(product: &Product, artifact_dir: &Path) -> Output {
    callisto(
        &product.root,
        &[
            "release",
            "artifact-manifest",
            "--intent",
            product.intent.to_str().unwrap(),
            "--artifact-dir",
            artifact_dir.to_str().unwrap(),
            "--out",
            product.external.path().join("artifact-manifest.json").to_str().unwrap(),
        ],
    )
}

fn assert_refused(product: &Product, out: &Output, code: &str) {
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(!out.status.success(), "must be refused: {stderr}");
    assert!(stderr.contains(code), "must fail with {code}: {stderr}");
    assert!(
        !product.external.path().join("artifact-manifest.json").exists(),
        "a refused run must not write a manifest"
    );
}

#[test]
fn a_manifest_covers_exactly_the_declared_assets_and_ignores_everything_else() {
    let product = product();
    let out = manifest(&product, &product.artifacts);
    assert!(out.status.success(), "{}", String::from_utf8_lossy(&out.stderr));
    let written: serde_json::Value =
        serde_json::from_slice(&fs::read(product.external.path().join("artifact-manifest.json")).unwrap()).unwrap();
    let entries = written["entries"].as_array().unwrap();
    assert_eq!(entries.len(), PRODUCT_ASSETS.len());
    let text = serde_json::to_string(&written).unwrap();
    assert!(!text.contains("hidden-metadata") && !text.contains("unlisted-artifact"));
}

#[test]
fn a_symlinked_asset_is_refused_even_when_it_points_at_a_real_file() {
    let product = product();
//! Each error code names one condition: a user's mistake never reports the internal-defect code, and
//! `callisto.toml` syntax errors, unknown keys and misfit values report different codes.
#[path = "common/release_harness.rs"]
mod release_harness;

use release_harness::*;

fn stderr_of(root: &std::path::Path, args: &[&str]) -> String {
    let out = callisto(root, args);
    assert!(!out.status.success(), "expected failure for {args:?}");
    String::from_utf8_lossy(&out.stderr).into_owned()
}

fn assert_only_code(stderr: &str, expected: &str) {
    for code in ["E111", "E325", "E326", "E327", "E328", "E171"] {
        assert_eq!(
            stderr.contains(code),
            code == expected,
            "{expected} only, got:\n{stderr}"
        );
    }
}

#[test]
fn pending_from_that_is_not_a_sha_is_a_user_error_not_an_internal_invariant() {
    let (dir, _) = release_commit_fixture();
    assert_only_code(&stderr_of(dir.path(), &["release", "pending", "--from", "abc"]), "E327");
}

#[test]
fn pending_from_a_commit_that_is_not_a_release_commit_is_a_user_error() {
    let (dir, _) = release_commit_fixture();
    let missing = "a".repeat(40);
    assert_only_code(
        &stderr_of(dir.path(), &["release", "pending", "--from", &missing]),
        "E328",
    );
}

fn config_error(toml: &str) -> String {
    let (dir, _) = release_commit_fixture();
    std::fs::write(dir.path().join("callisto.toml"), toml).unwrap();
    stderr_of(dir.path(), &["status"])
}

#[test]
fn config_unknown_key_reports_e325() {
    assert_only_code(&config_error("bogus = 1\n"), "E325");
    assert_only_code(&config_error("[changesets]\nbogus = 1\n"), "E325");
}

#[test]
fn config_syntax_error_reports_e111() {
    assert_only_code(&config_error("[changesets\n"), "E111");
}

#[test]
fn config_value_of_the_wrong_type_reports_e326() {
    assert_only_code(&config_error("[changesets]\ndir = 5\n"), "E326");
}
