fn documented_codes() -> BTreeSet<String> {
    let docs = fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/../../docs/errors.md")).unwrap();
    docs.lines()
        .filter_map(|line| line.strip_prefix("| E"))
