#[test]
fn every_documented_code_is_classified_usage_or_runtime_exactly_once() {
    let mut seen = BTreeSet::new();
    let classified = USAGE_CODES
        .iter()
        .chain(USAGE_WHEN_FROM_FLAG_CODES)
